import{d as e,i as t}from"./index-BVdLvPw-.js";import{t as n}from"./BlogPost-BCN0DswP.js";var r=t();function i(){return(0,r.jsxs)(n,{path:`/blog-local-seo-checklist`,children:[(0,r.jsx)(`p`,{children:`When customers search for a service 'near me', Google shows a map with a short list of businesses before the regular results. Getting into that list can transform enquiries for local businesses.`}),(0,r.jsx)(`p`,{children:`Google decides which businesses to show based on three broad factors: relevance (how well your profile matches the search), distance (how far you are from the searcher or the location they typed) and prominence (how well known and well reviewed you are). You can't change your distance, but most of this checklist improves relevance and prominence.`}),(0,r.jsx)(`h2`,{children:`The checklist`}),(0,r.jsxs)(`ol`,{children:[(0,r.jsx)(`li`,{children:`Claim and verify your Google Business Profile.`}),(0,r.jsx)(`li`,{children:`Choose the most accurate primary category, plus relevant secondary ones.`}),(0,r.jsx)(`li`,{children:`Use the same business name, address and phone everywhere online.`}),(0,r.jsx)(`li`,{children:`Add your services, service areas and opening hours.`}),(0,r.jsx)(`li`,{children:`Upload real photos of your team, premises and work.`}),(0,r.jsx)(`li`,{children:`Post updates and offers regularly.`}),(0,r.jsx)(`li`,{children:`Ask happy customers for reviews, and reply to every review.`}),(0,r.jsx)(`li`,{children:`Create a page on your website for each main service and location.`}),(0,r.jsx)(`li`,{children:`Make sure your website is fast and works well on mobiles.`}),(0,r.jsx)(`li`,{children:`List your business in reputable directories for your industry.`})]}),(0,r.jsx)(`h2`,{children:`Working through each step`}),(0,r.jsx)(`h3`,{children:`1. Claim and verify your profile`}),(0,r.jsx)(`p`,{children:`Search for your business on Google Maps. If a profile already exists, claim it rather than creating a duplicate. Google will ask you to verify, which may be by video, phone, email or another method depending on your business. Keep the login under a company account, not a staff member's personal Gmail, so you don't lose access when people leave.`}),(0,r.jsx)(`h3`,{children:`2. Pick the right categories`}),(0,r.jsx)(`p`,{children:`Your primary category has a big influence on which searches you appear for. Choose the one that best describes your main business, such as "Plumber" rather than "Contractor". Add secondary categories only for services you genuinely offer.`}),(0,r.jsx)(`h3`,{children:`3. Keep your details consistent`}),(0,r.jsx)(`p`,{children:`Your name, address and phone number (often called NAP) should match across your website, Google, Facebook, directories and industry listings. Use your real business name. Google's guidelines don't allow extra keywords or locations in the name, and stuffing them in can get a profile suspended.`}),(0,r.jsx)(`h3`,{children:`4. Services, areas and hours`}),(0,r.jsx)(`p`,{children:`If you visit customers rather than having them come to you, set yourself up as a service-area business and hide your street address. List the suburbs or regions you actually cover. Keep opening hours current, and add special hours for public holidays so customers don't turn up to a closed door.`}),(0,r.jsx)(`h3`,{children:`5. Real photos`}),(0,r.jsx)(`p`,{children:`Add photos of your shopfront, so people recognise it, plus your team, vehicles and finished work. Real photos build trust far better than stock images. Add new ones every so often rather than uploading fifty on day one.`}),(0,r.jsx)(`h3`,{children:`6. Regular posts`}),(0,r.jsx)(`p`,{children:`Profile posts let you share news, offers and events. They won't transform rankings on their own, but an active profile looks cared for. A short post every week or two, with a photo and a clear call to action, is plenty.`}),(0,r.jsx)(`h3`,{children:`7. Reviews and replies`}),(0,r.jsx)(`p`,{children:`Reviews influence both rankings and whether people choose you. Ask customers at the moment they are happiest, such as when a job is finished, and send a direct review link by text or email. Reply to every review, positive or negative, calmly and briefly. Don't offer discounts or gifts in exchange for reviews, and don't only ask customers you think will be positive, as both go against Google's policies.`}),(0,r.jsx)(`h3`,{children:`8. Service and location pages`}),(0,r.jsx)(`p`,{children:`Your Google profile links to your website, and Google reads that site to understand what you do. Create a separate page for each main service, and for key locations if you genuinely serve them. Each page needs useful, specific content: what the service includes, who it suits, the areas you cover and how to get in touch. Avoid copying the same page and only swapping the suburb name.`}),(0,r.jsx)(`h3`,{children:`9. Fast, mobile-friendly website`}),(0,r.jsxs)(`p`,{children:[`Most 'near me' searches happen on phones. If your site is slow or awkward on mobile, people tap back and call the next business. Our guide to `,(0,r.jsx)(e,{to:`/blog-core-web-vitals`,children:`Core Web Vitals`}),` explains how to check your site's speed, and good `,(0,r.jsx)(e,{to:`/website-development`,children:`website development`}),` makes it the default rather than an afterthought.`]}),(0,r.jsx)(`h3`,{children:`10. Reputable directories`}),(0,r.jsx)(`p`,{children:`Focus on quality, not quantity. Apple Maps, Bing Places, the main local directories and your industry association listings are worth having. Hundreds of low-quality directory submissions are not.`}),(0,r.jsx)(`h2`,{children:`Common mistakes`}),(0,r.jsxs)(`ul`,{children:[(0,r.jsx)(`li`,{children:`Creating a second profile instead of claiming the existing one.`}),(0,r.jsx)(`li`,{children:`Adding keywords or suburbs to the business name.`}),(0,r.jsx)(`li`,{children:`Using a virtual office or PO box as your address, which is against the guidelines.`}),(0,r.jsx)(`li`,{children:`Letting hours, phone numbers or website links go out of date after a move.`}),(0,r.jsx)(`li`,{children:`Ignoring negative reviews, or arguing with reviewers in public.`}),(0,r.jsx)(`li`,{children:`Setting up the profile once and never touching it again.`})]}),(0,r.jsx)(`h2`,{children:`Measure what matters`}),(0,r.jsx)(`p`,{children:`Track calls, direction requests and website clicks from your profile each month, not just rankings.`}),(0,r.jsx)(`p`,{children:`The Performance section of your Business Profile shows these interactions. Add tracking tags to your website link so you can see profile visits separately in your analytics. Rankings vary depending on where each searcher is standing, so a single ranking check from your office tells you little. Enquiries and calls tell you whether it is working.`}),(0,r.jsxs)(`p`,{children:[`Local SEO builds over months. For faster results while it grows, `,(0,r.jsx)(e,{to:`/google-meta-ads`,children:`Google and Meta ads`}),` can put you in front of local searchers straight away, and broader `,(0,r.jsx)(e,{to:`/seo`,children:`SEO services`}),` help your website rank beyond the map.`]}),(0,r.jsx)(`h2`,{children:`Frequently asked questions`}),(0,r.jsx)(`h3`,{children:`Can I appear in the map results if I work from home?`}),(0,r.jsx)(`p`,{children:`Yes. Set up as a service-area business, hide your home address and list the areas you serve. You still need to verify the business, but your address won't be shown publicly.`}),(0,r.jsx)(`h3`,{children:`How long does local SEO take to work?`}),(0,r.jsx)(`p`,{children:`It varies with competition and how established your business is. Fixing basic profile errors can help fairly quickly, while reviews, content and reputation build over several months.`}),(0,r.jsx)(`h3`,{children:`Can I have a profile for each suburb I serve?`}),(0,r.jsx)(`p`,{children:`No. Google only allows a profile for each real location where you serve customers in person or are staffed during business hours. Use service areas and website pages to cover the suburbs you travel to.`}),(0,r.jsx)(`h3`,{children:`Should I reply to old reviews I've never answered?`}),(0,r.jsx)(`p`,{children:`Yes, especially negative ones. A late, polite reply still shows future customers that you listen and care.`}),(0,r.jsxs)(`p`,{children:[`Our `,(0,r.jsx)(e,{to:`/local-listing`,children:`Local Listing`}),` service and Near Me plan handle all of this for you.`]})]})}export{i as default};